function mobilityView(){const lower=/Lower|Run|Tempo|Long|Hike/i.test(day().focus),items=mobilityItemsForDay(lower),pseudo={title:lower?'Lower / Run Prep':'Upper Prep',exercises:items};const firstTarget=allTasks(day()).find(t=>isStrength(t[2])||isRun(t[2]));return `<div class="card mobility-intro"><div class="label">TODAY'S MOVEMENT PREP</div><h3>${lower?'Run + lower-body readiness':'Upper-body readiness'}</h3><p class="small muted">Mobility prepares range and control. ⚡ Plyometric exercises are explosive power work, not stretching. Check Today for the exact time IXHUA placed each block.</p></div><div class="exercise-log-list">${items.map((e,i)=>movementCard(e,i,pseudo)).join('')}</div>`;}
function trainingView(){const d=day(),target=state.selectedTraining||allTasks(d).find(t=>isTraining(t[2]))?.[2]||d.focus;if(state.selectedTraining){if(isStrength(target))state.trainingTab='strength';else if(isMobility(target))state.trainingTab='mobility';else if(isRun(target))state.trainingTab='running';else if(isCardio(target))state.trainingTab='cardio';}const w=trainingForTask(target),tab=state.trainingTab||'strength';return `${dayStrip()}<div class="hero workout-hero"><div class="label">${esc(d.date)} • TRAINING</div><h2>${tab==='strength'?(w?.title||'Strength'):tab==='cardio'?'Cardio':tab==='running'?'Running':'Mobility'}</h2><p>Simple logging first. Detail appears only when you ask for it.</p></div><section class="section"><div class="training-tabs"><button data-training-tab="strength" class="seg-btn ${tab==='strength'?'active':''}">Strength</button><button data-training-tab="cardio" class="seg-btn ${tab==='cardio'?'active':''}">Cardio</button><button data-training-tab="running" class="seg-btn ${tab==='running'?'active':''}">Running</button><button data-training-tab="mobility" class="seg-btn ${tab==='mobility'?'active':''}">Mobility</button></div></section>${tab==='strength'?`<section class="section"><div class="section-head"><h3>Workout</h3><span>Weight + reps + rest.</span></div><div class="exercise-log-list">${(w||D.workouts['Upper Body A']).exercises.map((e,i)=>exerciseCard(e,i,w||D.workouts['Upper Body A'])).join('')}</div></section>`:tab==='cardio'?`<section class="section">${cardioView()}</section>`:tab==='running'?`<section class="section">${runningPlan()}</section>`:`<section class="section">${mobilityView()}</section>`}`;}
const macroTarget=()=> (state.athlete?window.IXHUA_ATHLETE_NUTRITION?.targets(state.athlete,state.macroGoals):state.macroGoals||window.REBUILD_ENGINE?.nutritionTarget(state.profile))||{cal:0,p:0,c:0,f:0,missingProfile:true};
