function sheet09(title,body){const previous=document.activeElement,m=document.createElement('dialog');m.className='sheet09';m.innerHTML=`<div class="sheet-handle"></div><div class="modal-head"><div><div class="label">IXHUA / YOUR TRAINING</div><h2>${esc(title)}</h2></div><button class="modal-close" aria-label="Close">×</button></div>${body}`;document.body.append(m);m.showModal();m.querySelector('.modal-close').onclick=()=>m.close();m.addEventListener('close',()=>{m.remove();previous?.focus();});m.addEventListener('click',e=>{if(e.target===m&&e.clientY<m.getBoundingClientRect().top)m.close();});return m;}
function muscleModel09(e){const regions=muscleRegions(e),primary=String(e.primary||'').toLowerCase();const spots={chest:[[25,29],[33,29]],shoulders:[[18,25],[40,25],[65,25],[87,25]],biceps:[[15,36],[43,36]],triceps:[[63,36],[90,36]],core:[[29,40]],quads:[[24,65],[35,65]],calves:[[24,85],[36,85],[70,85],[82,85]],hips:[[29,53]],upperback:[[76,29]],lats:[[70,37],[82,37]],glutes:[[76,55]],hamstrings:[[70,66],[82,66]]};const dots=regions.flatMap(r=>(spots[r]||[]).map(([x,y])=>`<i class="muscle-hotspot09 ${primary.includes(r.replace('upperback','back'))?'primary09':'secondary09'}" style="--x:${x}%;--y:${y}%" aria-hidden="true"></i>`)).join('');const labels=regions.map(r=>`<span>${esc(r==='upperback'?'upper back':r)}</span>`).join('');return `<figure class="muscle-model09" aria-label="3D anatomical view highlighting ${esc(regions.join(', '))} for ${esc(e.name)}"><div class="model-stage09"><div class="scanline09" aria-hidden="true"></div><img src="assets/anatomy-3d-front-back.png" alt="Front and back three-dimensional muscular anatomy"><div class="muscle-lights09">${dots}</div><div class="model-badge09"><b>3D MUSCLE MAP</b><small>Primary + supporting muscles</small></div></div><figcaption>${labels}</figcaption></figure>`;}
